        ["revision_ingestion_attempts_envelope_check"] = "CHECK (((evidence IS NULL) OR ((((evidence ->> 'version'::text) = evidence_version) AND (((evidence -> 'scope'::text) ->> 'organizationId'::text) = (provenance_organization_id)::text) AND (((evidence -> 'scope'::text) ->> 'projectId'::text) = (provenance_project_id)::text) AND (((evidence -> 'scope'::text) ->> 'mappingId'::text) = (provenance_mapping_id)::text) AND (((evidence -> 'scope'::text) ->> 'revisionId'::text) = (provenance_revision_id)::text) AND ((evidence ->> 'nativeDigest'::text) = provenance_native_digest) AND (((evidence -> 'backendProfile'::text) ->> 'backendId'::text) = provenance_backend_id) AND (((evidence -> 'backendProfile'::text) ->> 'engineRevision'::text) = provenance_engine_revision) AND (((evidence -> 'backendProfile'::text) ->> 'backendBuild'::text) = provenance_backend_build) AND (((evidence -> 'backendProfile'::text) ->> 'adapterBuild'::text) = provenance_adapter_build) AND ((evidence -> 'confirmed'::text) = to_jsonb(provenance_confirmed)) AND ((evidence ->> 'status'::text) = backend_status) AND ((evidence -> 'isValid'::text) = COALESCE(to_jsonb(is_valid), 'null'::jsonb)) AND ((evidence -> 'totalIssueCount'::text) = to_jsonb(total_issue_count)) AND ((evidence -> 'emittedIssueCount'::text) = to_jsonb(emitted_issue_count)) AND ((evidence -> 'truncated'::text) = to_jsonb(issues_truncated)) AND\nCASE\n    WHEN (jsonb_typeof((evidence -> 'diagnostics'::text)) = 'array'::text) THEN (((jsonb_array_length((evidence -> 'diagnostics'::text)) >= 0) AND (jsonb_array_length((evidence -> 'diagnostics'::text)) <= 128)) AND ((is_valid IS NULL) OR (jsonb_array_length((evidence -> 'diagnostics'::text)) = emitted_issue_count)))\n    ELSE false\nEND) IS TRUE)))",
        ["revision_ingestion_attempts_error_check"] = "CHECK ((last_error = ANY (ARRAY['needs_source'::text, 'storage_integrity'::text, 'storage_io'::text, 'backend_unavailable'::text, 'backend_failure'::text, 'timed_out'::text, 'canceled'::text, 'isolation_failure'::text, 'protocol_failure'::text, 'reserved_profile_unavailable'::text, 'evidence_limit'::text])))",
        ["revision_ingestion_attempts_evidence_size_check"] = "CHECK (((evidence IS NULL) OR (octet_length((evidence)::text) <= 8388608)))",
        ["revision_ingestion_attempts_provenance_check"] = "CHECK (((num_nonnulls(provenance_confirmed, provenance_organization_id, provenance_project_id, provenance_mapping_id, provenance_revision_id, provenance_native_digest, provenance_backend_id, provenance_engine_revision, provenance_backend_build, provenance_adapter_build) = ANY (ARRAY[0, 10])) AND ((provenance_confirmed IS NULL) OR ((provenance_organization_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (provenance_project_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (provenance_mapping_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (provenance_revision_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (provenance_native_digest ~ '^[0-9a-f]{64}$'::text) AND ((octet_length(provenance_backend_id) >= 1) AND (octet_length(provenance_backend_id) <= 128)) AND (char_length(btrim(provenance_backend_id)) > 0) AND ((octet_length(provenance_engine_revision) >= 1) AND (octet_length(provenance_engine_revision) <= 256)) AND (char_length(btrim(provenance_engine_revision)) > 0) AND ((octet_length(provenance_backend_build) >= 1) AND (octet_length(provenance_backend_build) <= 2048)) AND (char_length(btrim(provenance_backend_build)) > 0) AND ((octet_length(provenance_adapter_build) >= 1) AND (octet_length(provenance_adapter_build) <= 256)) AND (char_length(btrim(provenance_adapter_build)) > 0)))))",
        ["revision_ingestion_attempts_shape_check"] = "CHECK (((((completion_kind IS NULL) AND (num_nonnulls(backend_status, provenance_confirmed, is_valid, total_issue_count, emitted_issue_count, issues_truncated, evidence_version, evidence, reused_attempt_generation, reused_admission, last_error) = 0)) OR ((completion_kind = 'validation'::text) AND (verified_stage_at IS NOT NULL) AND (backend_status IS NOT NULL) AND (provenance_confirmed IS NOT NULL) AND (total_issue_count IS NOT NULL) AND (emitted_issue_count IS NOT NULL) AND (issues_truncated IS NOT NULL) AND (evidence_version = 'weft.ingestion-validation.v1'::text) AND (evidence IS NOT NULL) AND (jsonb_typeof(evidence) = 'object'::text) AND (reused_attempt_generation IS NULL) AND (reused_admission IS NULL) AND (last_error IS NULL)) OR ((completion_kind = 'operational_failure'::text) AND (num_nonnulls(backend_status, is_valid, total_issue_count, emitted_issue_count, issues_truncated, evidence_version, evidence, reused_attempt_generation, reused_admission) = 0) AND (last_error IS NOT NULL) AND (((last_error = 'evidence_limit'::text) AND (admission_classification = 'rejected_resource_limit'::text)) OR ((last_error <> 'evidence_limit'::text) AND (provenance_confirmed IS NULL) AND (admission_classification = 'retryable_failure'::text)))) OR ((completion_kind = 'reused_evidence'::text) AND (verified_stage_at IS NOT NULL) AND (num_nonnulls(backend_status, provenance_confirmed, is_valid, total_issue_count, emitted_issue_count, issues_truncated, evidence_version, evidence, last_error) = 0) AND (admission_classification = 'reused_evidence'::text) AND ((reused_attempt_generation >= 1) AND (reused_attempt_generation <= (generation - 1))) AND (reused_admission = ANY (ARRAY['eligible_valid'::text, 'eligible_decoded_invalid'::text])))) IS TRUE))",
