        ["revision_ingestions_ids_check"] = "CHECK (((operation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (idempotency_key <> '00000000-0000-0000-0000-000000000000'::uuid) AND (future_mapping_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (future_revision_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (native_object_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND ((lease_owner_id IS NULL) OR (lease_owner_id <> '00000000-0000-0000-0000-000000000000'::uuid)) AND ((lease_token IS NULL) OR (lease_token <> '00000000-0000-0000-0000-000000000000'::uuid)) AND ((expected_head_revision_id IS NULL) OR (expected_head_revision_id <> '00000000-0000-0000-0000-000000000000'::uuid))))",
        ["revision_ingestions_intent_check"] = "CHECK (((fingerprint_version = 1) AND (intent_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (operation_kind = ANY (ARRAY['create'::text, 'append'::text])) AND (head_condition = ANY (ARRAY['any'::text, 'equal'::text]))))",
        ["revision_ingestions_kind_check"] = "CHECK ((((operation_kind = 'create'::text) AND (target_mapping_id IS NULL) AND (create_name IS NOT NULL) AND (create_description IS NOT NULL) AND (head_condition = 'any'::text)) OR ((operation_kind = 'append'::text) AND (target_mapping_id = future_mapping_id) AND (target_mapping_id IS NOT NULL) AND (create_name IS NULL) AND (create_description IS NULL))))",
        ["revision_ingestions_native_check"] = "CHECK (((native_class = 'native'::text) AND (native_digest ~ '^[0-9a-f]{64}$'::text) AND ((native_byte_count >= 1) AND (native_byte_count <= 4194304)) AND ((effective_native_byte_limit >= native_byte_count) AND (effective_native_byte_limit <= 4194304)) AND (logical_entry_document = 'entry.native.json'::text) AND (dependency_manifest_id = 'weft.dependencies.empty.v1'::text)))",
        ["revision_ingestions_phase_check"] = "CHECK ((phase = ANY (ARRAY['reserved'::text, 'staged'::text, 'ready'::text, 'committed'::text, 'rejected'::text, 'head_conflict'::text, 'attempt_exhausted'::text])))",
        ["revision_ingestions_profile_check"] = "CHECK ((((octet_length(backend_id) >= 1) AND (octet_length(backend_id) <= 128)) AND (char_length(btrim(backend_id)) > 0) AND ((octet_length(engine_revision) >= 1) AND (octet_length(engine_revision) <= 256)) AND (char_length(btrim(engine_revision)) > 0) AND ((octet_length(backend_build) >= 1) AND (octet_length(backend_build) <= 2048)) AND (char_length(btrim(backend_build)) > 0) AND ((octet_length(adapter_build) >= 1) AND (octet_length(adapter_build) <= 256)) AND (char_length(btrim(adapter_build)) > 0) AND ((octet_length(admission_policy_id) >= 1) AND (octet_length(admission_policy_id) <= 128)) AND (char_length(btrim(admission_policy_id)) > 0)))",
        ["revision_ingestions_stage_check"] = "CHECK (((num_nonnulls(verified_stage_generation, verified_stage_at) = ANY (ARRAY[0, 2])) AND ((verified_stage_generation IS NULL) OR ((verified_stage_generation >= 1) AND (verified_stage_generation <= lease_generation))) AND ((phase <> ALL (ARRAY['staged'::text, 'ready'::text, 'committed'::text, 'head_conflict'::text])) OR (verified_stage_generation IS NOT NULL))))",
